// Tracked inputs own boot and launch facts; stale generated bytes refuse tests and bundling.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
const read = (path) => readFileSync(new URL(path, import.meta.url), "utf8");
const setup = read("../../scripts/aws/host_setup.py");
const extract = (name) => {
  const match = setup.match(new RegExp(`^${name} = "([^"]+)"$`, "m"));
  if (!match) throw new Error(`host_setup.py: expected one literal ${name}; update embed-host.mjs`);
  return match[1];
};
const script = read("../../scripts/aws/machine.sh");
if (script.split("# @settings\n").length !== 2) throw new Error("machine.sh needs exactly one settings marker");
const port = read("../../src/net/server.rs").match(/^const PORT: u16 = ([0-9]+);$/m);
if (!port) throw new Error("server.rs: expected one PORT; update embed-host.mjs");
const policy = JSON.parse(read("../../scripts/aws/host-policy.json"));
const volume = policy.Statement.find((s) => s.Resource.endsWith?.(":*:volume/*"));
const tags = setup.match(/^TAGS = (.+)$/m);
if (!tags) throw new Error("host_setup.py: TAGS missing");
const output = `// Generated by scripts/embed-host.mjs from tracked inputs. Do not edit.\nexport const machineScript = ${JSON.stringify(script)};\nexport const host = ${JSON.stringify({
  region: extract("REGION"), parameter: extract("PARAMETER"), tags: JSON.parse(tags[1]),
  ...JSON.parse(read("../../scripts/aws/host-image.json")), port: Number(port[1]),
  iops: volume.Condition.NumericLessThanEquals["ec2:VolumeIops"],
  throughput: volume.Condition.NumericLessThanEquals["ec2:VolumeThroughput"],
})} as const;\n`;
const dest = new URL("../src/host.generated.ts", import.meta.url);
if (process.argv.includes("--check")) {
  if (readFileSync(dest, "utf8") !== output) throw new Error("host embedding is stale: run node scripts/embed-host.mjs from backend");
} else writeFileSync(dest, output);
